/**
 * Static prerender - meta-tag injection approach.
 *
 * For each route, reads dist/index.html, injects the correct
 * title / description / og tags, and writes to dist/[path]/index.html.
 *
 * No browser required. Covers the main SEO benefit: crawlers and social
 * media scrapers receive per-page head content instead of the generic
 * fallback from index.html.
 *
 * Run after `vite build` via the postbuild npm hook.
 */

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { getCardSeoOverride } from '../src/data/cardSeoOverrides.js'
import { TESTS } from '../src/data/tests/index.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const DIST = path.resolve(__dirname, '../dist')
const SITE_URL = 'https://lovtaro.kr'

// Cloudflare Pages serves directory-based output at trailing-slash URLs.
// canonical / sitemap / JSON-LD / breadcrumbs must match the served URL form
// or Google reports "redirect error" from canonical/308 mismatch.
function canonicalUrl(urlPath) {
  if (urlPath === '/' || urlPath === '') return `${SITE_URL}/`
  return `${SITE_URL}${urlPath.replace(/\/$/, '')}/`
}

