// Major Arcana slug mapping for OG images (matches cardImages.js)
const OG_SLUG_MAP = {
  priestess: 'high-priestess',
  wheel: 'wheel-of-fortune',
  hanged: 'hanged-man',
}

// Generate card detail routes from card data
for (const card of [...CARDS, ...MINOR_CARDS]) {
  const ogSlug = OG_SLUG_MAP[card.id] || card.id
  const seo = getCardSeoOverride(card.id)
  ROUTES.push({
    path: `/cards/${card.id}`,
    title: seo?.title || `${card.name}(${card.nameEn}) 타로 카드 의미 - 정방향 역방향 연애 해석 | Lovtaro`,
    description: seo?.description || `${card.name}(${card.nameEn}) 타로 카드 정방향·역방향 의미와 연애 해석. 키워드: ${card.keywords.join(', ')}. 무료 타로 카드 의미 사전.`,
    ogImage: `${SITE_URL}/images/cards-png/${ogSlug}.png`,
  })
}

// ── 심리테스트 라우트 (허브 + 테스트별 intro) ──────────────────────────────
ROUTES.push({
  path: '/test',
  title: '연애 심리테스트 - 나를 닮은 연애 타로 유형 찾기 | Lovtaro',
  description: '질문에 답하고 나를 닮은 연애 타로 유형을 찾아보세요. 연애 스타일, 연애 성향을 알아보는 무료 연애 심리테스트 모음, Lovtaro.',
})
for (const test of TESTS) {
  ROUTES.push({
    path: `/test/${test.slug}`,
    title: test.metaTitle,
    description: test.metaDescription,
  })
}

// ── JSON-LD builders ──────────────────────────────────────────────────────
// JSON.stringify 결과에 섞이면 </script> 블록을 조기 종료시키므로 이스케이프
function escapeJsonLd(jsonStr) {
  return jsonStr.replace(/<\/script/gi, '<\\/script').replace(/<!--/g, '<\\!--')
}

function buildBreadcrumb(routePath, routeTitle) {
  const segments = routePath.split('/').filter(Boolean)
  const items = [{ name: '홈', url: canonicalUrl('/') }]
  let accumulated = ''
  segments.forEach((seg, i) => {
    accumulated += `/${seg}`
    const isLast = i === segments.length - 1
    const name = isLast ? routeTitle.split(' - ')[0].split(' | ')[0] : decodeLabel(seg)
    items.push({ name, url: canonicalUrl(accumulated) })
  })
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((it, idx) => ({
      '@type': 'ListItem',
      position: idx + 1,
      name: it.name,
      item: it.url,
    })),
  }
}

function decodeLabel(seg) {
  const labels = {
    today: '오늘의 연애 카드',
    reading: '타로 리딩',
    mind: '상대방 속마음 타로',
    love: '러브타로',
    reunion: '재회 가능성 타로',
    contact: '연락 올까 타로',
    yesno: 'Yes/No 타로',
    compatibility: '궁합 타로',
    '3cards': '3장 리딩',
    cards: '타로 카드 의미 사전',
    history: '리딩 기록',
    link: '링크',
    privacy: '개인정보처리방침',
    about: 'Lovtaro 소개',
    contact: '문의하기',
    'editorial-policy': '편집 방침',
    disclaimer: '면책 조항',
    guide: '연애 타로 가이드',
    dream: '꿈해몽 사전',
    test: '연애 심리테스트',
  }
  return labels[seg] || seg
}

