function buildCardDetailMain(card, detail, imageUrl) {
  const keywordsStr = card.keywords.join(', ')
  return {
    '@type': 'Article',
    headline: `${card.name}(${card.nameEn}) 타로 카드 의미`,
    description: `${card.name} 타로 카드의 정방향, 역방향 의미와 연애 해석. 키워드: ${keywordsStr}.`,
    image: imageUrl,
    author: { '@id': `${SITE_URL}#organization` },
    publisher: { '@id': `${SITE_URL}#organization` },
    inLanguage: 'ko',
    about: {
      '@type': 'Thing',
      name: `${card.name} (${card.nameEn})`,
      description: keywordsStr,
    },
  }
}

function buildCardFAQ(card, detail) {
  if (!detail || !detail.upright || !detail.reversed) return null
  return {
    '@type': 'FAQPage',
    mainEntity: [
      {
        '@type': 'Question',
        name: `${card.name}(${card.nameEn}) 정방향의 의미는?`,
        acceptedAnswer: { '@type': 'Answer', text: detail.upright.core },
      },
      {
        '@type': 'Question',
        name: `${card.name} 정방향 연애 해석은?`,
        acceptedAnswer: { '@type': 'Answer', text: detail.upright.love },
      },
      {
        '@type': 'Question',
        name: `${card.name}(${card.nameEn}) 역방향의 의미는?`,
        acceptedAnswer: { '@type': 'Answer', text: detail.reversed.core },
      },
      {
        '@type': 'Question',
        name: `${card.name} 역방향 연애 해석은?`,
        acceptedAnswer: { '@type': 'Answer', text: detail.reversed.love },
      },
    ],
  }
}

function buildGuideMain(guide) {
  return {
    '@type': 'Article',
    headline: guide.title,
    description: guide.description,
    url: canonicalUrl(`/guide/${guide.slug}`),
    datePublished: guide.createdAt,
    dateModified: guide.updatedAt || guide.createdAt,
    author: { '@id': `${SITE_URL}#organization` },
    publisher: { '@id': `${SITE_URL}#organization` },
    inLanguage: 'ko',
    image: guide.ogImage || `${SITE_URL}/og-image.png`,
  }
}

function buildGuideFAQ(guide) {
  if (!guide.faq || !guide.faq.length) return null
  return {
    '@type': 'FAQPage',
    mainEntity: guide.faq.map(item => ({
      '@type': 'Question',
      name: item.question,
      acceptedAnswer: { '@type': 'Answer', text: item.answer },
    })),
  }
}

// 가이드 본문을 #app에 정적으로 주입할 HTML로 생성.
// 크롤러/AdSense 봇이 JS 렌더링 없이 본문을 읽도록 함.
// createApp().mount('#app')는 마운트 시 컨테이너를 비우고 다시 그리므로
// JS 활성 환경에서는 Vue가 즉시 이 정적 본문을 교체한다 (hydration 아님).
function buildGuideBodyHtml(guide) {
  const sections = (guide.sections || []).map(s => {
    const heading = s.heading ? `<h2 class="guide-detail__section-heading">${escapeHtml(s.heading)}</h2>` : ''
    // content는 우리가 작성한 신뢰된 정적 HTML (<p>, <ul> 등). 그대로 삽입.
    return `<section class="guide-detail__section">${heading}<div class="guide-detail__section-content">${s.content}</div></section>`
  }).join('')

  const faq = (guide.faq && guide.faq.length)
    ? `<div class="guide-detail__faq"><h2 class="guide-detail__faq-title">자주 묻는 질문</h2><dl class="guide-detail__faq-list">${
        guide.faq.map(f => `<div class="guide-detail__faq-item"><dt class="guide-detail__faq-q">${escapeHtml(f.question)}</dt><dd class="guide-detail__faq-a">${escapeHtml(f.answer)}</dd></div>`).join('')
      }</dl></div>`
    : ''

  return `<div class="guide-detail"><article><header class="guide-detail__header"><h1 class="guide-detail__title">${escapeHtml(guide.title)}</h1><p class="guide-detail__desc">${escapeHtml(guide.description)}</p></header><div class="guide-detail__body">${sections}</div>${faq}</article></div>`
}

