// 꿈해몽 본문을 #app에 정적 주입 (크롤러가 JS 없이 본문을 읽도록). 클래스는
// DreamDetailPage.vue와 동일하게 dream-detail 프리픽스를 사용한다.
function buildDreamBodyHtml(dream) {
  const summary = dream.summary
    ? `<div class="dream-detail__summary"><p class="dream-detail__summary-text">${escapeHtml(dream.summary)}</p></div>`
    : ''

  const sections = (dream.sections || []).map(s => {
    const heading = s.heading ? `<h2 class="dream-detail__section-heading">${escapeHtml(s.heading)}</h2>` : ''
    return `<section class="dream-detail__section">${heading}<div class="dream-detail__section-content">${s.content}</div></section>`
  }).join('')

  const faq = (dream.faq && dream.faq.length)
    ? `<div class="dream-detail__faq"><h2 class="dream-detail__faq-title">자주 묻는 질문</h2><dl class="dream-detail__faq-list">${
        dream.faq.map(f => `<div class="dream-detail__faq-item"><dt class="dream-detail__faq-q">${escapeHtml(f.question)}</dt><dd class="dream-detail__faq-a">${escapeHtml(f.answer)}</dd></div>`).join('')
      }</dl></div>`
    : ''

  // 관련 꿈은 실제 <a href>로 주입 - 크롤러가 꿈↔꿈 내부링크(토픽 클러스터)를 보도록
  const related = (dream.relatedDreams && dream.relatedDreams.length)
    ? `<div class="dream-detail__related"><p class="dream-detail__related-label">관련 꿈</p><div class="dream-detail__related-list">${
        dream.relatedDreams.map(d => `<a class="dream-detail__related-card" href="/dream/${d.slug}/">${escapeHtml(d.label)}</a>`).join('')
      }</div></div>`
    : ''

  return `<div class="dream-detail"><article><header class="dream-detail__header"><h1 class="dream-detail__title">${escapeHtml(dream.title)}</h1><p class="dream-detail__desc">${escapeHtml(dream.description)}</p></header>${summary}<div class="dream-detail__body">${sections}</div>${faq}${related}</article></div>`
}

// 꿈해몽 허브(/dream) 본문을 정적 주입 - 크롤러/AI가 인트로 텍스트 + 전체 꿈 내부링크를 읽도록
function buildDreamHubBodyHtml(dreams) {
  const intro = `<p class="dream-index__intro">꿈은 일어날 일을 예고하기보다 지금 내 마음을 비추는 거울에 가까워요. 러브타로 꿈해몽 사전은 전통적인 해석 위에 연애와 관계의 신호를 더해, 전 애인 꿈부터 좋아하는 사람 꿈, 키스하는 꿈까지 마음의 결을 함께 읽어드려요. 단정이 아닌 가능성의 언어로 풀어요.</p>`
  const items = (dreams || []).map(d =>
    `<li class="dream-index__item"><h2 class="dream-index__item-title"><a href="/dream/${d.slug}/">${escapeHtml(d.title)}</a></h2><p class="dream-index__item-desc">${escapeHtml(d.description)}</p></li>`
  ).join('')
  return `<div class="dream-index"><div class="dream-index__header"><h1 class="dream-index__title">꿈해몽 사전</h1><p class="dream-index__desc">연애 관점으로 풀어보는 꿈 해석</p></div>${intro}<ul class="dream-index__list">${items}</ul></div>`
}

// 카드 상세 본문을 #app에 정적으로 주입할 HTML로 생성.
// CardDetailPage.vue 템플릿 구조/클래스를 미러링하며, 크롤러(특히 JS 렌더가
// 약한 네이버)가 정방향·역방향 본문 전체를 JS 없이 읽도록 한다.
// JS 활성 환경에서는 Vue가 마운트 시 이 정적 본문을 즉시 교체한다.
const CARD_ENERGY_LABEL = { positive: '긍정적 에너지', neutral: '중립적 에너지', challenging: '도전적 에너지' }

function cardParagraphs(text, cls) {
  const klass = cls ? ` class="${cls}"` : ''
  return String(text || '')
    .split(/\n+/)
    .map(t => t.trim())
    .filter(Boolean)
    .map(t => `<p${klass}>${escapeHtml(t)}</p>`)
    .join('')
}

function buildCardBodyHtml(card) {
  const keywords = (card.keywords || [])
    .map(kw => `<span class="card-detail__keyword">${escapeHtml(kw)}</span>`)
    .join('')
  const hero = `<div class="card-detail__hero"><div class="card-detail__hero-content"><h1 class="card-detail__name">${escapeHtml(card.name)}</h1><p class="card-detail__name-en">${escapeHtml(card.nameEn)}</p><div class="card-detail__tags"><span class="card-detail__energy">${CARD_ENERGY_LABEL[card.energy] || ''}</span><span class="card-detail__element">${escapeHtml(card.element || '')}</span></div><div class="card-detail__keywords">${keywords}</div></div></div>`

  const block = (title, text) => `<div class="card-detail__block"><h2 class="card-detail__block-title">${title}</h2>${cardParagraphs(text, 'card-detail__block-text')}</div>`
  const advice = (text) => `<div class="card-detail__advice">${cardParagraphs(text)}</div>`

  const section = (label, dirClass, data) =>
    `<div class="card-detail__section"><div class="card-detail__section-header"><span class="card-detail__direction card-detail__direction--${dirClass}">${label}</span></div>${block('핵심 의미', data.core)}${block('연애 해석', data.love)}${advice(data.advice)}</div>`

  // CardDetailPage.vue의 리딩 CTA와 동일 - 크롤러가 카드→무료리딩 내부 링크를 보도록
  const cta = `<div class="card-detail__cta"><p class="card-detail__cta-text">이 카드가 지금 내 연애에선 어떤 의미일까요?</p><div class="card-detail__cta-links"><a href="/reading/love/" class="card-detail__cta-btn">러브타로</a><a href="/reading/mind/" class="card-detail__cta-btn">상대방 속마음</a><a href="/reading/contact/" class="card-detail__cta-btn">연락 올까</a><a href="/reading/reunion/" class="card-detail__cta-btn">재회 가능성</a></div></div>`

  return `<div class="card-detail">${hero}${section('정방향', 'upright', card.upright)}${section('역방향', 'reversed', card.reversed)}${cta}</div>`
}

function buildReadingMain(route) {
  return {
    '@type': 'WebPage',
    name: route.title.split(' | ')[0],
    description: route.description,
    url: canonicalUrl(route.path),
    inLanguage: 'ko',
    isPartOf: { '@id': `${SITE_URL}#website` },
    primaryImageOfPage: route.ogImage ? { '@type': 'ImageObject', url: route.ogImage } : undefined,
  }
}

function buildGraph(route, { allCards, cardDetailMap } = {}) {
  const graph = []
  const isHome = route.path === '/'
  const isCardsList = route.path === '/cards'
  const cardDetailMatch = route.path.match(/^\/cards\/(.+)$/)
  const isReading = route.path.startsWith('/reading/') || route.path === '/today'
  const isGuideIndex = route.path === '/guide'
  const isGuideDetail = route.path.startsWith('/guide/') && route._guide
  const isDreamIndex = route.path === '/dream'
  const isDreamDetail = route.path.startsWith('/dream/') && route._dream

  if (isHome) {
    graph.push(buildOrganization(), buildWebSite(), buildHomeMain())
  } else if (isCardsList && allCards) {
    graph.push(buildCardsListMain(allCards))
  } else if (isGuideIndex) {
    graph.push({
      '@type': 'CollectionPage',
      name: '연애 타로 가이드',
      description: '연애 타로 카드 해석 가이드 모음',
      url: canonicalUrl('/guide'),
      inLanguage: 'ko',
      isPartOf: { '@id': `${SITE_URL}#website` },
    })
  } else if (isGuideDetail) {
    graph.push(buildGuideMain(route._guide))
    const faq = buildGuideFAQ(route._guide)
    if (faq) graph.push(faq)
  } else if (isDreamIndex) {
    graph.push({
      '@type': 'CollectionPage',
      name: '꿈해몽 사전',
      description: '연애 관점으로 풀어보는 꿈 해석 모음',
      url: canonicalUrl('/dream'),
      inLanguage: 'ko',
      isPartOf: { '@id': `${SITE_URL}#website` },
    })
  } else if (isDreamDetail) {
    graph.push(buildDreamMain(route._dream))
    const faq = buildDreamFAQ(route._dream)
    if (faq) graph.push(faq)
  } else if (cardDetailMatch) {
    const cardId = cardDetailMatch[1]
    const card = allCards.find(c => c.id === cardId)
    if (card) {
      graph.push(buildCardDetailMain(card, cardDetailMap[cardId], route.ogImage))
      const faq = buildCardFAQ(card, cardDetailMap[cardId])
      if (faq) graph.push(faq)
    }
  } else if (isReading) {
    graph.push(buildReadingMain(route))
  }

  graph.push(buildBreadcrumb(route.path, route.title))

  return { '@context': 'https://schema.org', '@graph': graph }
}

// ── Meta injection ─────────────────────────────────────────────────────────
function escapeAttr(str) {
  return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

// 텍스트 노드용 (따옴표는 변환 불필요)
function escapeHtml(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

function injectMeta(html, { path: urlPath, title, description, ogImage, jsonLd, noindex, _guide, _dream, _dreamHub, _card }) {
  const url = canonicalUrl(urlPath)
  const safeTitle = escapeAttr(title)
  const safeDesc = escapeAttr(description)
  const safeUrl = escapeAttr(url)
  const safeImg = escapeAttr(ogImage || `${SITE_URL}/og-image.png`)

  // <title>
  html = html.replace(/<title>[^<]*<\/title>/, `<title>${safeTitle}</title>`)

  // twitter:title / twitter:description use name= attribute
  html = html.replace(
    /(<meta name="description"\s+content=")[^"]*(")/,
    `$1${safeDesc}$2`,
  )
  html = html.replace(
    /(<meta name="twitter:title"\s+content=")[^"]*(")/,
    `$1${safeTitle}$2`,
  )
  html = html.replace(
    /(<meta name="twitter:description"\s+content=")[^"]*(")/,
    `$1${safeDesc}$2`,
  )
  html = html.replace(
    /(<meta name="twitter:image"\s+content=")[^"]*(")/,
    `$1${safeImg}$2`,
  )

  // og: tags use property= attribute
  html = html.replace(
    /(<meta property="og:title"\s+content=")[^"]*(")/,
    `$1${safeTitle}$2`,
  )
  html = html.replace(
    /(<meta property="og:description"\s+content=")[^"]*(")/,
    `$1${safeDesc}$2`,
  )
  html = html.replace(
    /(<meta property="og:url"\s+content=")[^"]*(")/,
    `$1${safeUrl}$2`,
  )
  html = html.replace(
    /(<meta property="og:image"\s+content=")[^"]*(")/,
    `$1${safeImg}$2`,
  )

  // canonical + alternate hreflang
  html = html.replace(
    /(<link rel="canonical"\s+href=")[^"]*(")/,
    `$1${safeUrl}$2`,
  )
  html = html.replace(
    /(<link rel="alternate"\s+hreflang="ko"\s+href=")[^"]*(")/,
    `$1${safeUrl}$2`,
  )

  // 검색엔진 색인 차단이 필요한 페이지 (예: /history - 사용자 로컬 데이터 의존, 첫 방문자에겐 항상 빈 상태)
  if (noindex) {
    const robotsMeta = '<meta name="robots" content="noindex, nofollow" />'
    if (/<meta name="robots"[^>]*>/.test(html)) {
      html = html.replace(/<meta name="robots"[^>]*>/, robotsMeta)
    } else {
      html = html.replace(/<\/head>/, `  ${robotsMeta}\n  </head>`)
    }
  }

  // JSON-LD 주입. useHead.js가 동일 id로 클라이언트에서 교체함.
  if (jsonLd) {
    const jsonText = escapeJsonLd(JSON.stringify(jsonLd))
    const script = `<script type="application/ld+json" id="lovtaro-jsonld">${jsonText}</script>`
    // 기존 같은 id script가 있으면 교체, 없으면 </head> 직전에 삽입
    if (/<script[^>]*id="lovtaro-jsonld"[^>]*>[\s\S]*?<\/script>/.test(html)) {
      html = html.replace(/<script[^>]*id="lovtaro-jsonld"[^>]*>[\s\S]*?<\/script>/, script)
    } else {
      html = html.replace(/<\/head>/, `  ${script}\n  </head>`)
    }
  }

  // 가이드 본문을 #app에 정적 주입 (크롤러가 JS 없이 본문을 읽도록)
  if (_guide) {
    const bodyHtml = buildGuideBodyHtml(_guide)
    html = html.replace(/<div id="app">\s*<\/div>/, `<div id="app">${bodyHtml}</div>`)
  }

  // 꿈해몽 본문을 #app에 정적 주입
  if (_dream) {
    const bodyHtml = buildDreamBodyHtml(_dream)
    html = html.replace(/<div id="app">\s*<\/div>/, `<div id="app">${bodyHtml}</div>`)
  }

  // 꿈해몽 허브(/dream) 인트로+목록을 #app에 정적 주입
  if (_dreamHub) {
    const bodyHtml = buildDreamHubBodyHtml(_dreamHub)
    html = html.replace(/<div id="app">\s*<\/div>/, `<div id="app">${bodyHtml}</div>`)
  }

  // 카드 상세 본문을 #app에 정적 주입 (네이버 등 JS 약한 크롤러 대응)
  if (_card) {
    const bodyHtml = buildCardBodyHtml(_card)
    html = html.replace(/<div id="app">\s*<\/div>/, `<div id="app">${bodyHtml}</div>`)
  }

  return html
}

// ── Main ──────────────────────────────────────────────────────────────────
async function run() {
  const indexPath = path.join(DIST, 'index.html')
  if (!fs.existsSync(indexPath)) {
    console.error('[prerender] dist/index.html not found - run vite build first')
    process.exit(1)
  }

  // 카드 상세 FAQ용 데이터 로드 (src는 빌드 후에도 남아있음)
  const { ALL_CARDS } = await import('../src/data/cardDictionary.js')
  const allCardsList = [...CARDS, ...MINOR_CARDS]

  // 가이드 본문(sections)은 단일 소스에서 로드. prerender 내부 GUIDES 미러는
  // FAQ JSON-LD용이라 sections가 없으므로, 본문 정적 주입은 src 데이터를 사용.
  const { default: SRC_GUIDES } = await import('../src/data/guides/index.js')
  const srcGuideMap = new Map(SRC_GUIDES.map(g => [g.slug, g]))

  // 꿈해몽: 단일 소스(src/data/dreams)를 직접 import해 라우트 생성.
  // 가이드와 달리 prerender 내부 미러 없이 src 객체를 그대로 _dream에 실어
  // JSON-LD(Main/FAQ)와 본문 주입을 모두 같은 데이터로 처리한다 (이중 관리 없음).
  const { default: SRC_DREAMS } = await import('../src/data/dreams/index.js')
  ROUTES.push({
    path: '/dream',
    title: '꿈해몽 사전 - 연애 관점으로 풀어보는 꿈 해석 | Lovtaro',
    description: '전 애인 꿈, 좋아하는 사람 꿈, 키스하는 꿈까지. 연애 관점으로 풀어보는 꿈해몽 사전. 전통 해몽 위에 마음의 신호를 더해 읽는 Lovtaro 꿈해몽.',
    _dreamHub: SRC_DREAMS,
  })
  for (const dream of SRC_DREAMS) {
    ROUTES.push({
      path: `/dream/${dream.slug}`,
      title: `${dream.title} | Lovtaro`,
      description: dream.description,
      ogImage: dream.ogImage || null,
      _dream: dream,
    })
  }

  const baseHtml = fs.readFileSync(indexPath, 'utf8')
  let success = 0

  for (const route of ROUTES) {
    const jsonLd = buildGraph(route, { allCards: allCardsList, cardDetailMap: ALL_CARDS })
    const guideForBody = route._guide ? (srcGuideMap.get(route._guide.slug) || route._guide) : null
    const cardMatch = route.path.match(/^\/cards\/(.+)$/)
    const cardForBody = cardMatch ? ALL_CARDS[cardMatch[1]] : null
    const html = injectMeta(baseHtml, { ...route, jsonLd, _guide: guideForBody, _card: cardForBody })

    if (route.path === '/') {
      fs.writeFileSync(indexPath, html, 'utf8')
    } else {
      const dir = path.join(DIST, route.path)
      fs.mkdirSync(dir, { recursive: true })
      fs.writeFileSync(path.join(dir, 'index.html'), html, 'utf8')
    }

    console.log(`  ✓ ${route.path}`)
    success++
  }

  console.log(`\n[prerender] ${success} pages written`)
}

run()
